package com.logssey.secretworker.usage;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;

class AwsUsageObserverTest {
    static final String KEY="AKIA"+"A".repeat(16),OTHER="AKIA"+"B".repeat(16),REGION="ap-northeast-2";
    static final Instant END=Instant.parse("2026-11-07T00:00:00Z"),START=END.minus(Duration.ofDays(7));
    final AwsUsageGateway gateway=mock(AwsUsageGateway.class);
    final List<Duration> sleeps=new ArrayList<>();final AtomicInteger rates=new AtomicInteger();
    AwsUsageObserver.Result run(){return new AwsUsageObserver(sleeps::add,100,5000).observe(gateway,REGION,KEY,START,END,()->{},rates::incrementAndGet);}
    AwsUsageGateway.Event event(String key,String raw){return new AwsUsageGateway.Event("11111111-1111-4111-8111-111111111111",key,"GetCallerIdentity","sts.amazonaws.com",END.minusSeconds(30),raw);}
    @Test void completeZeroIsScopedAndNotAnUnusedKeyClaim(){when(gateway.lookup(REGION,KEY,START,END,null)).thenReturn(new AwsUsageGateway.Page(List.of(),null));var result=run();assertThat(result.observationStatus()).isEqualTo("NOT_OBSERVED_IN_SCOPE");assertThat(result.coverageStatus()).isEqualTo("COMPLETE");assertThat(result.events()).isZero();assertThat(rates).hasValue(1);}
    @Test void providerIdentityAndResultAreNormalizedWithoutRawFields(){var raw="{\"eventVersion\":\"1.09\",\"eventName\":\"GetCallerIdentity\",\"managementEvent\":true,\"userIdentity\":{\"accessKeyId\":\""+KEY+"\"},\"sourceIPAddress\":\"PRIVATE_SOURCE\"}";when(gateway.lookup(REGION,KEY,START,END,null)).thenReturn(new AwsUsageGateway.Page(List.of(event(KEY,raw)),null));var result=run();assertThat(result.observations()).hasSize(1);var row=result.observations().getFirst();assertThat(row.actionCode()).isEqualTo("AUTHENTICATION");assertThat(row.operationCode()).isEqualTo("GetCallerIdentity");assertThat(row.actorAttribution()).isEqualTo("UNATTRIBUTED");assertThat(row.actionResult()).isEqualTo("SUCCESS");assertThat(row.toString()).doesNotContain(KEY,"PRIVATE_SOURCE","userIdentity");}
    @Test void wrongKeyCannotBecomeAnExactObservation(){when(gateway.lookup(REGION,KEY,START,END,null)).thenReturn(new AwsUsageGateway.Page(List.of(event(OTHER,"{}")),null));var result=run();assertThat(result.observations()).isEmpty();assertThat(result.observationStatus()).isEqualTo("UNAVAILABLE");assertThat(result.coverageStatus()).isEqualTo("PARTIAL");}
    @Test void contradictoryNestedKeyCannotBecomeAnExactObservation(){when(gateway.lookup(REGION,KEY,START,END,null)).thenReturn(new AwsUsageGateway.Page(List.of(event(KEY,"{\"userIdentity\":{\"accessKeyId\":\""+OTHER+"\"}}")),null));assertThat(run().observations()).isEmpty();}
    @Test void retriesOnlyTwoTimesAndPreservesSuccessfulPages(){when(gateway.lookup(REGION,KEY,START,END,null)).thenThrow(new AwsUsageFailure("USAGE_PROVIDER_UNAVAILABLE",true,null)).thenThrow(new AwsUsageFailure("USAGE_PROVIDER_UNAVAILABLE",true,null)).thenReturn(new AwsUsageGateway.Page(List.of(event(KEY,"{\"eventVersion\":\"1.09\",\"eventName\":\"GetCallerIdentity\"}")),"next"));when(gateway.lookup(REGION,KEY,START,END,"next")).thenThrow(new AwsUsageFailure("USAGE_ACCESS_DENIED",false,null));var result=run();assertThat(sleeps).hasSize(2);assertThat(result.observationStatus()).isEqualTo("OBSERVED");assertThat(result.coverageStatus()).isEqualTo("PARTIAL");assertThat(result.pages()).isEqualTo(1);verify(gateway,times(3)).lookup(REGION,KEY,START,END,null);verify(gateway).lookup(REGION,KEY,START,END,"next");}
    @Test void longRetryAfterReturnsToQueueWithoutSleepingLease(){Instant retry=Instant.now().plusSeconds(60);when(gateway.lookup(REGION,KEY,START,END,null)).thenThrow(new AwsUsageFailure("USAGE_RATE_LIMITED",true,retry));var result=run();assertThat(result.retryAt()).isEqualTo(retry);assertThat(sleeps).isEmpty();verify(gateway).lookup(REGION,KEY,START,END,null);}
    @Test void repeatedNextTokenAndLimitsArePartial(){when(gateway.lookup(REGION,KEY,START,END,null)).thenReturn(new AwsUsageGateway.Page(List.of(),"same"));when(gateway.lookup(REGION,KEY,START,END,"same")).thenReturn(new AwsUsageGateway.Page(List.of(),"same"));assertThat(run().reasonCodes()).contains("USAGE_PAGINATION_INVALID");var capped=new AwsUsageObserver(sleeps::add,1,50).observe(gateway,REGION,KEY,START,END,()->{},()->{});assertThat(capped.reasonCodes()).contains("USAGE_PAGE_LIMIT");assertThat(capped.coverageStatus()).isEqualTo("PARTIAL");}
    @Test void retryAfterAcceptsDatesAndBoundsUntrustedDelays(){Instant now=Instant.parse("2026-11-07T00:00:00Z");assertThat(AwsSdkUsageGateway.retryAfter("Sat, 7 Nov 2026 00:01:00 GMT",now)).isEqualTo(now.plusSeconds(60));assertThat(AwsSdkUsageGateway.retryAfter("99999999",now)).isEqualTo(now.plusSeconds(86400));assertThat(AwsSdkUsageGateway.retryAfter("malformed",now)).isNull();assertThat(AwsSdkUsageGateway.retryAfter("-1",now)).isNull();}
}
